1	    // The project-prompt request recorder (--project-prompt-requests).
2	    // Included inside class Scenario.
3	    //
4	    // tests/project_prompt asks a live model for one step at a known point of
5	    // a project chat. This plays each of its scripted conversations through
6	    // the real app up to that point -- the person's words, a canvas issue
7	    // button, a file opened -- with the model's outputs taken from the script
8	    // and every tool run for real, and keeps each request the script marks.
9	    // Only the script's words and calls are written by hand: the tool results,
10	    // the workspace context, the history and its replay rules are the app's.
11	    // The page's prompt and the tool list are checked against the files the
12	    // suite sends and left out of the output.
13	    //
14	    // At each kept request the script's "answers" reads are then called in
15	    // the same turn, and their results kept as the app returned them: the
16	    // suite answers a model's read with them. That ends the conversation, so
17	    // each kept request has a pass of its own, replaying the conversation
18	    // from the start, and no answer reaches another case's history.
19	
20	    // A person's edit of one or more print settings, through the print tab.
21	    void prompt_hand_edit(const nlohmann::json& changes)
22	    {
23	        DynamicPrintConfig diff;
24	        for (const auto& [key, value] : changes.items())
25	            diff.set_deserialize_strict(key, value.get<std::string>());
26	        wxGetApp().get_tab(Preset::TYPE_PRINT)->load_config(diff);
27	        wait_for([this] { return !m_plater->is_background_process_update_scheduled(); }, std::chrono::seconds(5));
28	    }
29	
30	    // The print settings and filament the first conversation started with.
31	    std::optional<DynamicPrintConfig> m_prompt_print;
32	    std::string                       m_prompt_filament;
33	
34	    // A new project keeps the edited print settings and the selected
35	    // filament, so an earlier conversation's changes are typed back and its
36	    // filament selected again.
37	    void prompt_restore_settings(const std::string& name)
38	    {
39	        PresetBundle& bundle = *wxGetApp().preset_bundle;
40	        if (!m_prompt_print) {
41	            m_prompt_print    = bundle.prints.get_edited_preset().config;
42	            m_prompt_filament = bundle.filaments.get_edited_preset().name;
43	            return;
44	        }
45	        const t_config_option_keys changed = bundle.prints.get_edited_preset().config.diff(*m_prompt_print);
46	        if (!changed.empty()) {
47	            DynamicPrintConfig back;
48	            back.apply_only(*m_prompt_print, changed);
49	            wxGetApp().get_tab(Preset::TYPE_PRINT)->load_config(back);
50	        }
51	        if (bundle.filaments.get_edited_preset().name != m_prompt_filament)
52	            SetupCommands::select_filament_preset(*m_plater, 0, m_prompt_filament);
53	        check(bundle.prints.get_edited_preset().config.diff(*m_prompt_print).empty() &&
54	                  bundle.filaments.get_edited_preset().name == m_prompt_filament,
55	              name + "_starts_from_the_first_settings");
56	    }
57	
58	    // The project each conversation starts from, with its current plate sliced.
59	    bool prompt_fixture(const std::string& kind, const std::string& name)
60	    {
61	        using namespace std::chrono_literals;
62	        prompt_restore_settings(name);
63	        if (kind == "overhang") {
64	            // print_issues_scenario's slab on one leg: slicing it warns.
65	            check(m_plater->new_project(true, true) != wxID_CANCEL, name + "_new_project");
66	            const std::string cube = std::string(JUSPRIN_SOURCE_DIR) + "/tests/data/test_stl/ASCII/20mmbox-LF.stl";
67	            const auto strategy = LoadStrategy::LoadModel | LoadStrategy::AddDefaultInstances | LoadStrategy::Silence;
68	            check(m_plater->load_files(std::vector<std::string>{cube}, strategy, false).size() == 1, name + "_cube_loaded");
69	            check(m_plater->load_files(std::vector<std::string>{write_overhang_stl()}, strategy, false).size() == 1,
70	                  name + "_overhang_loaded");
71	            PartPlateList& plates = m_plater->get_partplate_list();
72	            check(plates.get_plate(0)->add_instance(0, 0, true) == 0, name + "_cube_centred");
73	            check(plates.get_plate(0)->add_instance(1, 0, true) == 0, name + "_overhang_centred");
74	            m_plater->canvas3D()->reload_scene(true, true);
75	            move_object(1, Vec3d(70, 0, 0));
76	        } else {
77	            load_multi_plate_fixture();
78	        }
79	        const auto slice = [this](std::chrono::seconds limit) {
80	            wait_for([this] { return !m_plater->is_background_process_update_scheduled(); }, 10s);
81	            installed_shell()->status_row()->request_slice();
82	            return wait_for([this] {
83	                const auto* plate = m_plater->get_partplate_list().get_curr_plate();
84	                return plate && plate->is_slice_result_valid() && !m_plater->is_background_process_slicing();
85	            }, limit);
86	        };
87	        const bool sliced = slice(60s) || slice(120s);
88	        if (!sliced) {
89	            issue_monitor().refresh_now();
90	            for (const auto& issue : issues().issues)
91	                std::cerr << "HARNESS PROMPT " << name << " fixture issue " << issue.id << " '" << issue.message << "'\n";
92	        }
93	        check(sliced, name + "_fixture_sliced");
94	        installed_shell()->status_row()->request_prepare();
95	        wait_for([this] { return m_notebook->GetSelection() == MainFrame::tp3DEditor && !m_plater->is_preview_shown(); }, 20s);
96	
97	        Agent::AgentHost& host = project_host();
98	        if (!host.conversation().empty())
99	            host.on_page_message(nlohmann::json{{"protocol", Agent::Protocol::kName},
100	                                                {"version", Agent::Protocol::kVersion},
101	                                                {"id", "prompt-new-" + name},
102	                                                {"type", Agent::Protocol::kCreateConversation},
103	                                                {"payload", nlohmann::json::object()}}
104	                                     .dump());
105	        const bool fresh = wait_for([&host] { return host.conversation().empty() && !host.busy(); }, 10s);
106	        check(fresh, name + "_starts_an_empty_chat");
107	        return sliced && fresh;
108	    }
109	
110	    // "{{result/<pointer>}}" is the last tool result in this request;
111	    // "{{workspace/sessionId}}", "{{workspace/revision}}",
112	    // "{{workspace/activePlateId}}", "{{workspace/firstObjectId}}" (the
113	    // active plate's first object), "{{workspace/filamentPreset}}" and
114	    // "{{workspace/printerPreset}}" the project now; "{{object}}" the object
115	    // an "eachObject" answer is being read for.
116	    nlohmann::json prompt_fill(const nlohmann::json& value, const nlohmann::json& body, const std::string& name)
117	    {
118	        using nlohmann::json;
119	        if (value.is_object() || value.is_array()) {
120	            json filled = value;
121	            for (auto& [key, item] : filled.items())
122	                item = prompt_fill(item, body, name);
123	            return filled;
124	        }
125	        if (!value.is_string())
126	            return value;
127	        const std::string text = value;
128	        if (text.size() < 5 || text.rfind("{{", 0) != 0 || text.compare(text.size() - 2, 2, "}}") != 0)
129	            return value;
130	        const std::string path = text.substr(2, text.size() - 4);
131	        if (path == "object" && !m_prompt_object.empty())
132	            return m_prompt_object;
133	        if (path == "workspace/sessionId")
134	            return std::to_string(installed_shell()->workspace()->snapshot().session.value());
135	        if (path == "workspace/revision")
136	            return installed_shell()->workspace()->snapshot().revision;
137	        if (path == "workspace/filamentPreset")
138	            return installed_shell()->workspace()->snapshot().setup.filament_preset;
139	        if (path == "workspace/printerPreset")
140	            return installed_shell()->workspace()->snapshot().setup.printer_preset;
141	        if (path == "workspace/activePlateId" || path == "workspace/firstObjectId")
142	            for (const auto& plate : installed_shell()->workspace()->snapshot().plates)
143	                if (plate.active && (path == "workspace/activePlateId" || !plate.objects.empty()))
144	                    return std::to_string(path == "workspace/activePlateId" ? plate.id.value() : plate.objects.front().id.value());
145	        if (path.rfind("result/", 0) == 0) {
146	            const json& input = body.at("input");
147	            for (auto item = input.rbegin(); item != input.rend(); ++item)
148	                if (item->value("type", "") == "function_call_output") {
149	                    const json output = json::parse(item->at("output").get<std::string>());
150	                    const json::json_pointer pointer(path.substr(6));
151	                    if (output.contains("result") && output["result"].contains(pointer))
152	                        return output["result"][pointer];
153	                    break;
154	                }
155	        }
156	        check(false, name + "_fills " + text);
157	        return value;
158	    }
159	
160	    // Answers a held request with model output, as the service streams it.
161	    static void prompt_answer(HeldModelRequest& request, const nlohmann::json& output, const std::string& text)
162	    {
163	        using Event = Agent::AgentHttpEvent;
164	        const auto frame = [](const nlohmann::json& event) { return "event: message\ndata: " + event.dump() + "\n\n"; };
165	        if (!text.empty())
166	            request.answer(Event{Event::Kind::Data, frame({{"type", "response.output_text.delta"}, {"delta", text}}), {}, 0});
167	        request.answer(Event{Event::Kind::Data,
168	                             frame({{"type", "response.completed"}, {"response", {{"output", output}}}}), {}, 0});
169	        request.answer(Event{Event::Kind::Complete, {}, {}, 200});
170	    }
171	
172	    // The next request of this turn the model is asked, past any chat title.
173	    std::optional<HeldModelRequest> prompt_next_request()
174	    {
175	        for (;;) {
176	            if (!wait_for([] { return !g_held_model_requests.empty(); }, std::chrono::seconds(120)))
177	                return std::nullopt;
178	            HeldModelRequest request = std::move(g_held_model_requests.front());
179	            g_held_model_requests.pop_front();
180	            if (request.body.contains("tools"))
181	                return request;
182	            prompt_answer(request, nlohmann::json::array({{{"type", "message"}, {"role", "assistant"},
183	                                                           {"content", nlohmann::json::array({{{"type", "output_text"},
184	                                                                                               {"text", "Fixture chat"}}})}}}),
185	                          "Fixture chat");
186	        }
187	    }
188	
189	    std::string m_prompt_object;  // for "{{object}}"
190	
191	    // The answers' reads called after the kept request, in the same turn;
192	    // returns each with the result the app gave, as the model would read it.
193	    // A read marked "eachObject" is called once for every object on every
194	    // plate, and an "allSettings" entry with it once for every object.
195	    // An "allSettings" entry reads every setting of its scope:
196	    // the keys come from the app's own settings_search (an empty query lists
197	    // them all, page by page; those pages are not kept), then settings_get
198	    // reads them 32 at a time. With "keysOf" it reads, under its scope, the
199	    // keys of the scopes named, read before it, that are not its own: how
200	    // the app answers a name asked for under the wrong scope. The workspace block every result
201	    // carries is kept once, beside them, and left out of each result that
202	    // repeats it exactly.
203	    nlohmann::json prompt_answers(const std::string& name, HeldModelRequest request, const nlohmann::json& script_reads)
204	    {
205	        using nlohmann::json;
206	        json answers = json::array();
207	        int  calls   = 0;
208	        // One read in the turn; the result as the app gave it, or nothing.
209	        const auto call = [&](const std::string& tool, const json& arguments) -> std::optional<std::string> {
210	            const std::string call_id = "call_" + name + "_answer_" + std::to_string(++calls);
211	            prompt_answer(request, json::array({{{"type", "function_call"}, {"call_id", call_id}, {"name", tool},
212	                                                 {"arguments", arguments.dump()}}}), "");
213	            std::optional<HeldModelRequest> next = prompt_next_request();
214	            check(next.has_value(), name + "_answer_" + tool + "_returned");
215	            if (!next)
216	                return std::nullopt;
217	            request = std::move(*next);
218	            const std::string output = request.body.at("input").back().at("output");
219	            const bool succeeded = json::parse(output).value("state", "") == "succeeded";
220	            check(succeeded, name + "_answer_" + tool + "_succeeded");
221	            return succeeded ? std::optional<std::string>(output) : std::nullopt;
222	        };
223	        std::map<std::string, std::vector<std::string>> scope_keys;
224	        bool ok = true;
225	        for (const json& read : script_reads) {
226	            if (!ok)
227	                break;
228	            std::vector<std::string> objects{std::string()};
229	            if (read.value("eachObject", false)) {
230	                objects.clear();
231	                for (const auto& plate : installed_shell()->workspace()->snapshot().plates)
232	                    for (const auto& object : plate.objects)
233	                        objects.push_back(std::to_string(object.id.value()));
234	            }
235	            if (read.contains("allSettings")) {
236	                const std::string scope = read["allSettings"];
237	                for (const std::string& object : objects) {
238	                    if (!ok)
239	                        break;
240	                    m_prompt_object = object;
241	                    const json target = prompt_fill(read.value("target", json()), request.body, name);
242	                    std::vector<std::string> keys;
243	                    if (read.contains("keysOf")) {
244	                        const auto& own = scope_keys[scope];
245	                        for (const json& other : read["keysOf"])
246	                            for (const std::string& key : scope_keys[other.get<std::string>()])
247	                                if (std::find(own.begin(), own.end(), key) == own.end())
248	                                    keys.push_back(key);
249	                    } else if (scope_keys.count(scope)) {
250	                        keys = scope_keys[scope];  // every object of the scope has the same settings
251	                    } else {
252	                        std::string cursor;
253	                        do {
254	                            json search{{"scope", scope}, {"query", ""}, {"limit", 25}};
255	                            if (!target.is_null())
256	                                search["target"] = target;
257	                            if (!cursor.empty())
258	                                search["cursor"] = cursor;
259	                            const std::optional<std::string> page = call("settings_search", search);
260	                            if (!(ok = page.has_value()))
261	                                break;
262	                            const json result = json::parse(*page).at("result");
263	                            for (const json& item : result.at("items"))
264	                                keys.push_back(item.at("key"));
265	                            cursor = result.value("nextCursor", "");
266	                        } while (!cursor.empty());
267	                        scope_keys[scope] = keys;
268	                    }
269	                    for (std::size_t first = 0; ok && first < keys.size(); first += 32) {
270	                        json arguments{{"scope", scope},
271	                                       {"keys", std::vector<std::string>(keys.begin() + first, keys.begin() + std::min(keys.size(), first + 32))}};
272	                        if (!target.is_null())
273	                            arguments["target"] = target;
274	                        const std::optional<std::string> output = call("settings_get", arguments);
275	                        if ((ok = output.has_value()))
276	                            answers.push_back({{"tool", "settings_get"}, {"arguments", arguments}, {"output", *output}});
277	                    }
278	                    std::cerr << "HARNESS PROMPT " << name << " allSettings " << scope << (object.empty() ? "" : " " + object)
279	                              << (read.contains("keysOf") ? " (other scopes' keys)" : "") << " keys=" << keys.size() << '\n';
280	                }
281	                continue;
282	            }
283	            for (const std::string& object : objects) {
284	                m_prompt_object = object;
285	                const json arguments = prompt_fill(read.value("arguments", json::object()), request.body, name);
286	                const std::optional<std::string> output = call(read.at("call"), arguments);
287	                if (!(ok = output.has_value()))
288	                    break;
289	                answers.push_back({{"tool", read.at("call")}, {"arguments", arguments}, {"output", *output}});
290	            }
291	        }
292	        m_prompt_object.clear();
293	        prompt_answer(request, json::array(), "");
294	        wait_for([this] { return !g_held_model_requests.empty() || !project_host().busy(); }, std::chrono::seconds(10));
295	        json shared = json::object();
296	        for (json& answer : answers) {
297	            json output = json::parse(answer["output"].get<std::string>());
298	            const json block{{"workspace", output.value("workspace", json())}, {"workspaceRevision", output.value("workspaceRevision", json())}};
299	            if (shared.empty())
300	                shared = block;
301	            if (block != shared)
302	                continue;
303	            output.erase("workspace");
304	            output.erase("workspaceRevision");
305	            answer["output"] = output.dump();
306	            answer["sharedWorkspace"] = true;
307	        }
308	        return {{"reads", answers}, {"shared", shared}};
309	    }
310	
311	    // One step of a conversation: what the person does, then the model's
312	    // scripted outputs, one per request the app sends, until they run out.
313	    // The record point numbered `target` is kept, with its answers, and ends
314	    // the conversation (2); otherwise 1, or 0 on a failure.
315	    int prompt_step(const std::string& name, const nlohmann::json& step, nlohmann::json& recorded,
316	                    const nlohmann::json& tools, const std::string& instructions, const nlohmann::json& reads,
317	                    int& point, int target)
318	    {
319	        using nlohmann::json;
320	        using namespace std::chrono_literals;
321	        Agent::AgentHost& host = project_host();
322	        const json        scripted = step.value("replies", json::array());
323	        std::deque<json>  replies(scripted.begin(), scripted.end());
324	
325	        if (step.contains("say")) {
326	            static int next = 0;
327	            ++next;
328	            host.on_page_message(json{{"protocol", Agent::Protocol::kName},
329	                                      {"version", Agent::Protocol::kVersion},
330	                                      {"id", "prompt-" + std::to_string(next)},
331	                                      {"type", Agent::Protocol::kUserMessage},
332	                                      {"payload", {{"clientMessageId", "prompt-c-" + std::to_string(next)}, {"text", step["say"]}}}}
333	                                     .dump());
334	        } else if (step.contains("issue")) {
335	            // A setting typed in by hand, the issue OrcaSlicer reports for
336	            // it, and a press of one of the issue's two buttons.
337	            prompt_hand_edit(step.at("set"));
338	            const std::string setting = step.at("set").begin().key();
339	            std::string       issue_id;
340	            wait_for([&] {
341	                issue_monitor().refresh_now();
342	                for (const auto& issue : issues().issues)
343	                    if (issues().checked && issue.source == PrintIssues::IssueSource::Validation && issue.setting == setting)
344	                        issue_id = issue.id;
345	                return !issue_id.empty();
346	            }, 30s);
347	            check(!issue_id.empty(), name + "_issue_reported");
348	            const std::string outcome = issue_id.empty() ? "" : installed_shell()->submit_issue(issue_id, step["issue"]).outcome;
349	            std::cerr << "HARNESS PROMPT " << name << " issue " << issue_id << " outcome=" << outcome << '\n';
350	            check(outcome == "started", name + "_issue_sent_to_the_chat");
351	        } else if (step.contains("open")) {
352	            // A project someone saved with an author note in its description,
353	            // written by the app's own exporter, then opened.
354	            if (!m_plater->model().model_info)
355	                m_plater->model().model_info = std::make_shared<ModelInfo>();
356	            m_plater->model().model_info->description = step.value("description", "");
357	            const fs::path file = fs::path(data_dir()) / (step["open"].get<std::string>() + ".3mf");
358	            check(m_plater->export_3mf(file, SaveStrategy::SplitModel | SaveStrategy::ShareMesh | SaveStrategy::Silence) >= 0,
359	                  name + "_project_saved");
360	            check(m_plater->new_project(true, true) != wxID_CANCEL, name + "_saved_project_closed");
361	            m_plater->load_project(from_u8(file.string()), "-");
362	        }
363	
364	        bool expect_failure = false;
365	        int  calls          = 0;
366	        for (;;) {
367	            // The chat title is asked for after a reply ends; no case reads it.
368	            wait_for([&] { return !g_held_model_requests.empty() || (replies.empty() && !host.busy()); }, 120s);
369	            if (g_held_model_requests.empty()) {
370	                if (!replies.empty()) {
371	                    const auto snapshot = installed_shell()->workspace()->snapshot();
372	                    std::cerr << "HARNESS PROMPT " << name << " waiting: slicing.running=" << snapshot.slicing.running
373	                              << " orca_slicing=" << m_plater->is_background_process_slicing();
374	                    for (const auto& plate : snapshot.plates)
375	                        std::cerr << " plate " << plate.id.value() << " active=" << plate.active << " sliced=" << plate.sliced;
376	                    issue_monitor().refresh_now();
377	                    for (const auto& issue : issues().issues)
378	                        std::cerr << " | issue " << issue.id << " '" << issue.message << "'";
379	                    for (const auto& activity : host.tools().activities())
380	                        std::cerr << " | " << activity.tool << '=' << Agent::tool_state_name(activity.state);
381	                    std::cerr << '\n';
382	                }
383	                break;
384	            }
385	            HeldModelRequest request = std::move(g_held_model_requests.front());
386	            g_held_model_requests.pop_front();
387	            if (!request.body.contains("tools")) {
388	                prompt_answer(request, json::array({{{"type", "message"}, {"role", "assistant"},
389	                                                     {"content", json::array({{{"type", "output_text"}, {"text", "Fixture chat"}}})}}}),
390	                              "Fixture chat");
391	                continue;
392	            }
393	            const json& input = request.body.at("input");
394	            if (!input.empty() && input.back().value("type", "") == "function_call_output") {
395	                const json output = json::parse(input.back().at("output").get<std::string>());
396	                const std::string state = output.value("state", "");
397	                std::cerr << "HARNESS PROMPT " << name << " result state=" << state
398	                          << (output.contains("error") ? " error=" + output["error"].value("code", "") : std::string()) << '\n';
399	                check((state == "failed") == expect_failure && state != "running", name + "_call_" + std::to_string(calls) + "_outcome");
400	            }
401	            if (replies.empty()) {
402	                check(false, name + "_unscripted_request");
403	                prompt_answer(request, json::array(), "");
404	                continue;
405	            }
406	            const json reply = replies.front();
407	            replies.pop_front();
408	            if (reply.contains("set"))
409	                prompt_hand_edit(reply["set"]);
410	            if (reply.contains("record") && point++ == target) {
411	                // The suite sends its own copies; they must be what the app sends.
412	                const std::string case_name = reply["record"];
413	                check(request.body.at("tools") == tools, case_name + "_tools_match_project_tools_json");
414	                check(request.body.at("instructions") == instructions, case_name + "_instructions_are_the_page_prompt");
415	                json kept = request.body;
416	                kept.erase("tools");
417	                kept.erase("instructions");
418	                const std::size_t items = input.size();
419	                const json recorded_reads = prompt_answers(case_name, std::move(request), reads);
420	                const json& answers = recorded_reads["reads"];
421	                recorded[case_name] = {{"body", kept}, {"answers", answers}, {"sharedWorkspace", recorded_reads["shared"]}};
422	                std::cerr << "HARNESS PROMPT recorded " << case_name << " input_items=" << items
423	                          << " bytes=" << kept.dump().size() << " answers=" << answers.size()
424	                          << " answer_bytes=" << answers.dump().size() << '\n';
425	                return 2;
426	            }
427	            json output = json::array();
428	            std::string text;
429	            if (reply.contains("text")) {
430	                text = reply["text"];
431	                output.push_back({{"type", "message"}, {"role", "assistant"},
432	                                  {"content", json::array({{{"type", "output_text"}, {"text", text}}})}});
433	            }
434	            if (reply.contains("call")) {
435	                ++calls;
436	                // The form the app replays a call in; a live model's own item
437	                // id and status are not reproducible.
438	                output.push_back({{"type", "function_call"},
439	                                  {"call_id", "call_" + name + "_" + std::to_string(calls)},
440	                                  {"name", reply["call"]},
441	                                  {"arguments", prompt_fill(reply.value("arguments", json::object()), request.body, name).dump()}});
442	                expect_failure = reply.value("fails", false);
443	                std::cerr << "HARNESS PROMPT " << name << " call " << reply["call"].get<std::string>() << ' '
444	                          << output.back()["arguments"].get<std::string>() << '\n';
445	            }
446	            prompt_answer(request, output, text);
447	        }
448	        check(replies.empty(), name + "_every_scripted_output_used");
449	        return replies.empty() ? 1 : 0;
450	    }
451	
452	    void record_prompt_requests()
453	    {
454	        using nlohmann::json;
455	        m_state->deadline = std::chrono::steady_clock::now() + std::chrono::minutes(30);
456	        const auto read = [](const fs::path& path) {
457	            std::ifstream file(path.string(), std::ios::binary);
458	            return std::string((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
459	        };
460	        const json script = json::parse(read(m_state->prompt_script), nullptr, false);
461	        const json tools  = json::parse(read(fs::path(JUSPRIN_SOURCE_DIR) / "tests/project_prompt/project_tools.json"), nullptr, false);
462	        const std::string instructions =
463	            read(fs::path(JUSPRIN_SOURCE_DIR) / "src/slic3r/GUI/JusPrin/AgentUI/src/projectInstructions.fixture.txt");
464	        check(script.is_object() && script.contains("conversations"), "prompt_script_read");
465	        check(tools.is_array() && !instructions.empty(), "prompt_tools_and_instructions_read");
466	        json recorded = json::object();
467	        const json reads = script.is_object() ? script.value("answers", json::array()) : json::array();
468	        bool ok = script.is_object() && tools.is_array();
469	        if (ok)
470	            for (const json& conversation : script["conversations"]) {
471	                const std::string name = conversation.at("name");
472	                int points = 0;
473	                for (const json& step : conversation.at("steps"))
474	                    for (const json& reply : step.value("replies", json::array()))
475	                        points += reply.contains("record") ? 1 : 0;
476	                // One pass per kept request: its answers end the conversation.
477	                for (int target = 0; ok && target < points; ++target) {
478	                    std::cerr << "HARNESS PROMPT conversation " << name << " point " << target << '\n';
479	                    if (!(ok = prompt_fixture(conversation.value("fixture", "plates"), name)))
480	                        break;
481	                    int point = 0, result = 1;
482	                    for (const json& step : conversation.at("steps"))
483	                        if (result == 1)
484	                            result = prompt_step(name, step, recorded, tools, instructions, reads, point, target);
485	                    check(result == 2, name + "_point_" + std::to_string(target) + "_kept");
486	                    ok = result == 2;
487	                }
488	                if (!ok)
489	                    break;
490	            }
491	        // The setting items of settings_get and settings_search results repeat
492	        // across reads and points: each distinct one is kept once, in
493	        // settingItems, and a result holds its index there instead.
494	        json items = json::array();
495	        std::map<std::string, std::size_t> index;
496	        for (auto& [case_name, kept] : recorded.items())
497	            for (json& answer : kept["answers"]) {
498	                if (answer["tool"] != "settings_get" && answer["tool"] != "settings_search")
499	                    continue;
500	                json output = json::parse(answer["output"].get<std::string>());
501	                for (const char* field : {"items", "unknownKeys"}) {
502	                    if (!output["result"].contains(field))
503	                        continue;
504	                    for (json& item : output["result"][field]) {
505	                        const auto [found, added] = index.emplace(item.dump(), items.size());
506	                        if (added)
507	                            items.push_back(item);
508	                        item = found->second;
509	                    }
510	                }
511	                answer["output"]       = output.dump();
512	                answer["settingItems"] = true;
513	            }
514	        std::ofstream output(m_state->prompt_requests.string(), std::ios::binary);
515	        output << json{{"settingItems", items}, {"cases", recorded}}.dump(1) << '\n';
516	        check(output.good(), "prompt_requests_written");
517	        finish();
518	    }
